CREATE TABLE sales (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), customer_id uuid, sale_date date NOT NULL, subtotal numeric(18,2) NOT NULL, tax numeric(18,2) NOT NULL DEFAULT 0, discount numeric(18,2) NOT NULL DEFAULT 0, total_amount numeric(18,2) NOT NULL, status text NOT NULL, FOREIGN KEY (organization_id,customer_id) REFERENCES customers(organization_id,id), UNIQUE(organization_id,id)); CREATE TABLE sale_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), sale_id uuid NOT NULL, product_id uuid NOT NULL, quantity numeric(18,3) NOT NULL, unit_price numeric(18,2) NOT NULL, discount numeric(18,2) NOT NULL DEFAULT 0, total numeric(18,2) NOT NULL, FOREIGN KEY (organization_id,sale_id) REFERENCES sales(organization_id,id), FOREIGN KEY (organization_id,product_id) REFERENCES products(organization_id,id)); CREATE INDEX sales_org_date_idx ON sales(organization_id,sale_date DESC);
